import {
  mkdtemp,
  readFile,
  rm,
} from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";

import {
  build,
} from "esbuild";

const ROOT = fileURLToPath(new URL("../", import.meta.url));
const ENTRY = path.join(
  ROOT,
  "apps",
  "bim-explorer-web",
  "source-worker.mjs",
);
const OUTPUT = path.join(
  ROOT,
  "apps",
  "bim-explorer-web",
  "source-worker.bundle.mjs",
);

async function createBundle(output) {
  await build({
    banner: {
      js:
        "// Generated by scripts/build-vscode-worker.mjs. " +
        "Do not edit directly.",
    },
    bundle: true,
    entryPoints: [ENTRY],
    external: ["web-ifc"],
    format: "esm",
    legalComments: "none",
    minify: false,
    outfile: output,
    platform: "browser",
    sourcemap: false,
    target: ["es2022"],
  });
}

export async function checkVscodeWorkerBundle() {
  const temporary = await mkdtemp(
    path.join(tmpdir(), "bim-explorer-worker-"),
  );
  try {
    const generated = path.join(temporary, "worker.mjs");
    await createBundle(generated);
    const [expected, observed] = await Promise.all([
      readFile(OUTPUT),
      readFile(generated),
    ]);
    if (!expected.equals(observed)) {
      throw new Error(
        "VS Code Worker bundle is stale; run npm run build:vscode-worker",
      );
    }
    process.stdout.write(
      `VS Code Worker bundle check passed: ` +
        `${expected.byteLength} bytes\n`,
    );
  } finally {
    await rm(temporary, {
      force: true,
      recursive: true,
    });
  }
}

async function main() {
  if (
    process.argv.length === 3 &&
    process.argv[2] === "--check"
  ) {
    await checkVscodeWorkerBundle();
    return;
  }
  if (process.argv.length !== 2) {
    throw new TypeError(
      "usage: node scripts/build-vscode-worker.mjs [--check]",
    );
  }
  await createBundle(OUTPUT);
  const body = await readFile(OUTPUT);
  process.stdout.write(
    `VS Code Worker bundle built: ${body.byteLength} bytes\n`,
  );
}

if (
  process.argv[1] &&
  path.resolve(process.argv[1]) ===
    fileURLToPath(import.meta.url)
) {
  await main();
}
